TYPE.TEST:


SetFunctionName("Matrix33()");

Matrix33 m;

// The matrix is not initialized to any specific values, so we don't need to validate anything.



#ifdef HOST_TESTING

        SetFunctionName("Matrix33(const fpu::Matrix33Template<FloatClassRHS> &_m)");

        ::rw::math::fpu::Matrix33Template<double> doubleUnalignedMatrix;
        ::rw::math::fpu::Matrix33Template<float> floatUnalignedMatrix;
        ::rw::math::fpu::Matrix33Template<double> doubleAlignedMatrix;
        ::rw::math::fpu::Matrix33Template<float> floatAlignedMatrix;

        doubleUnalignedMatrix.Set(
            0, 1, 0,
            -1, 0, 0,
            2, 3, 4
            );
        floatUnalignedMatrix.Set(
            0, 1, 0,
            -1, 0, 0,
            2, 3, 4
            );
        doubleAlignedMatrix.Set(
            0, 1, 0,
            -1, 0, 0,
            2, 3, 4
            );
        floatAlignedMatrix.Set(
            0, 1, 0,
            -1, 0, 0,
            2, 3, 4
            );

        Matrix33 ref;
        ref.Set(
            0, 1, 0,
            -1, 0, 0,
            2, 3, 4
            );

        Matrix33 test_doubleUnalignedMatrix(doubleUnalignedMatrix);
        Matrix33 test_floatUnalignedMatrix(doubleUnalignedMatrix);
        Matrix33 test_doubleAlignedMatrix(doubleUnalignedMatrix);
        Matrix33 test_floatAlignedMatrix(doubleUnalignedMatrix);

        Validate(IsSimilar(test_doubleUnalignedMatrix, ref) &&
                 IsSimilar(test_floatUnalignedMatrix, ref) &&
                 IsSimilar(test_doubleAlignedMatrix, ref) &&
                 IsSimilar(test_floatAlignedMatrix, ref));

#endif



SetFunctionName("Matrix33(Matrix33)");

Matrix33 m0((float_basic_type)1.0f, (float_basic_type)2.0f, (float_basic_type)3.0f,
            (float_basic_type)4.0f, (float_basic_type)5.0f, (float_basic_type)6.0f,
            (float_basic_type)7.0f, (float_basic_type)8.0f, (float_basic_type)9.0f);

Matrix33 m1(m0);

Validate(IsSimilar(m0, m1));

SetFunctionName("Matrix33(FloatType m0, FloatType m1, FloatType m2, FloatType m3, FloatType m4, FloatType m5, FloatType m6, FloatType m7, FloatType m8)");
Matrix33 m( (float_basic_type) 2.0f, (float_basic_type) 3.0f, (float_basic_type) 4.0f, (float_basic_type) 5.0f, (float_basic_type) 6.0f, (float_basic_type) 7.0f, (float_basic_type) 8.0f, (float_basic_type) 9.0f, (float_basic_type) 10.0f);
Validate( m.GetElem(0) == float_test_type( 2.0f) && m.GetElem(1) == float_test_type( 3.0f) && m.GetElem(2) == float_test_type( 4.0f) && m.GetElem(3) == float_test_type( 5.0f) && m.GetElem(4) == float_test_type( 6.0f) && m.GetElem(5) == float_test_type( 7.0f) && m.GetElem(6) == float_test_type( 8.0f) && m.GetElem(7) == float_test_type( 9.0f) && m.GetElem(8) == float_test_type(10.0f) );

#ifdef HOST_TESTING
SetFunctionName("Matrix33(VecFloat m0, VecFloat m1, VecFloat m2, VecFloat m3, VecFloat m4, VecFloat m5, VecFloat m6, VecFloat m7, VecFloat m8)");
