SetFunctionName("SetZero()");

Matrix33 zero((float_test_type)0.0, (float_test_type)0.0, (float_test_type)0.0,
              (float_test_type)0.0, (float_test_type)0.0, (float_test_type)0.0,
              (float_test_type)0.0, (float_test_type)0.0, (float_test_type)0.0);
Matrix33 m((float_test_type)1.0f, (float_test_type)3.0f, (float_test_type)3.0f,
           (float_test_type)0.4f, (float_test_type)0.5f, (float_test_type)2.0f,
           (float_test_type)1.0f, (float_test_type)7.0f, (float_test_type)9.0f);
m.SetZero();

Validate(IsSimilar(m, zero));



SetFunctionName("SetIdentity()");

Matrix33 identity((float_test_type)1.0,(float_test_type)0.0,(float_test_type)0.0,
                  (float_test_type)0.0,(float_test_type)1.0,(float_test_type)0.0,
                  (float_test_type)0.0,(float_test_type)0.0,(float_test_type)1.0);
Matrix33 m;
m.SetIdentity();

Validate(IsSimilar(m, identity));

