m.Set(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f);
r = Mult(v3, m); // test with non-aliasing

ra.Set(6.0f, -1.0f, -3.0f);
ra = Mult(ra, m);  // test with aliasing

Vector3 ref(
          m.GetElem(0, 0) * v3.X() + m.GetElem(1, 0) * v3.Y() + m.GetElem(2, 0) * v3.Z(),
          m.GetElem(0, 1) * v3.X() + m.GetElem(1, 1) * v3.Y() + m.GetElem(2, 1) * v3.Z(),
          m.GetElem(0, 2) * v3.X() + m.GetElem(1, 2) * v3.Y() + m.GetElem(2, 2) * v3.Z());

Validate(IsSimilar(r, ref) && IsSimilar(ra, ref));



SetFunctionName("Mult(const Matrix33 &a, const Matrix33 &b)");

Matrix33 a, b, r, ref;

a.Set(1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f);
b.Set(2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f);


r = Mult(a, b);

for (int32_t i = 0; i < 3; ++i)
{
    ref.SetElem(i, 0, a.GetElem(i, 0) * b.GetElem(0, 0) + a.GetElem(i, 1) * b.GetElem(1, 0) + a.GetElem(i, 2) * b.GetElem(2, 0) );
    ref.SetElem(i, 1, a.GetElem(i, 0) * b.GetElem(0, 1) + a.GetElem(i, 1) * b.GetElem(1, 1) + a.GetElem(i, 2) * b.GetElem(2, 1) );
    ref.SetElem(i, 2, a.GetElem(i, 0) * b.GetElem(0, 2) + a.GetElem(i, 1) * b.GetElem(1, 2) + a.GetElem(i, 2) * b.GetElem(2, 2) );
}

Validate(IsSimilar(r, ref));



