SetFunctionName("IsSimilar(const Matrix33 &a, const Matrix33 &b, float_t epsilon = rw::math::kSmallFloat)");

Matrix33 a, b, c, d, e;

a.Set(
     1.0f,  2.0f,  0.0f,
    -1.0f,  1.0f,  1.0f,
     1.0f,  2.0f,  3.0f
    );

b.Set(
    1.0f,  2.0f,  0.0f,
   -1.0f,  1.0f,  1.0f,
    1.0f,  2.0f,  3.0f
    );

c.Set(
    2.0f,  2.0f,  0.0f,
   -1.0f,  1.0f,  1.0f,
    1.0f,  2.0f,  3.0f
    );

d.Set(
    1.0f,  2.0f,  0.0f,
   -1.0f,  2.0f,  1.0f,
    1.0f,  2.0f,  3.0f
    );

e.Set(
    1.0f,  2.0f,  0.0f,
   -1.0f,  1.0f,  1.0f,
    2.0f,  2.0f,  3.0f
    );

bool perturbTest = true;
for(int row=0;row<3;row++)
{
    for(int col=0;col<3;col++)
    {
        Matrix33 testMatrix = a;
        // Perturb the matrix to make it different from a.
        testMatrix.GetElem(row, col) = testMatrix.GetElem(row, col) + (float_test_type)1.0f;
        if( IsSimilar(a,testMatrix) )
        {
            perturbTest = false;
            break;
        }
    }
}

Validate(IsSimilar(a, b) && !IsSimilar(a, c) && !IsSimilar(a, d) && !IsSimilar(a, e) && perturbTest);




#if !defined EA_PLATFORM_PS3_SPU
        SetFunctionName("IsAnyNaN(Matrix33 v)");

        float zero = 0.0f;
        float_test_type nan = float_test_type(zero / zero);
        int numPermutations = 1 << Matrix33::NumberOfCols;
        bool result = true;
        // Doing all possible permutations of the matrix could be pretty slow. Instead,
        // all permutations along the diagonal will be done.
        for( int curPermutation=0;curPermutation<numPermutations;curPermutation++)
        {
            Matrix33 mat;
            mat.SetZero();
            for( int elem = 0; elem < Matrix33::NumberOfCols; elem++ )
            {
                if( curPermutation & (1<<elem) )
                {
                    mat.SetElem( elem, elem, nan );
                }
            }
            if( curPermutation == 0 )
            {
                // All bits are zero so the matrix has no NaN's
                result &= !IsAnyNaN(mat);
            }
            else
            {
                // At least one element is NaN.
                result &= IsAnyNaN(mat);
            }
        }
        Validate(result);
#endif



