SetFunctionName("Matrix33FromQuaternion(const Quaternion &q)");

Quaternion q;
Matrix33 r, ref;
float_test_type angle = -PI + 0.0001f;
float_test_type zero = 0.0f;

for (; angle < float_test_type(PI); angle += float_test_type(0.25f))
{
    q.Set(Sin(angle / float_test_type(2.0f)), zero, zero, Cos(angle / float_test_type(2.0f)));

    ref.Set(
        float_test_type(1.0f), zero, zero,
        zero, Cos(angle), Sin(angle),
        zero, Sin(-angle), Cos(angle)
        );

    r = Matrix33FromQuaternion(q);

    Validate(IsSimilar(r, ref));
}



