Validate( IsSimilar(result, ref, (float_basic_type) 0.001f) &&
          IsSimilar(angle, (float_basic_type)0.25f) );



SetFunctionName("Multiple conversion routine Test");

// This test converts as follows:
//  1. Euler => Matrix33
//  2. Matrix33 => Quaternion
//  3. Quaternion => Matrix33
//  3. Matrix33 => Euler angles
float halfPi = 0.5f * 3.14159265359f;
for( int za=0; za<4; ++za )
{
    for( int ya=0; ya<4; ++ya )
    {
        for( int xa=0; xa<4; ++xa )
        {
            // Create eulerAngles
            Vector3 eulerAngles(xa * halfPi, ya * halfPi, za * halfPi);
            Matrix33 rotMatrix = Matrix33FromEulerXYZ(eulerAngles);
            Quaternion quat = QuaternionFromMatrix33(rotMatrix);

            Matrix33 rotMatrix2 = Matrix33FromQuaternion(quat);
            Vector3 eulerAngles2 = EulerXYZFromMatrix33(rotMatrix);
            // Validate rotation matrix
            Validate(IsSimilar(rotMatrix, rotMatrix2));
            // Validate euler angles
            // Note: the euler angles can't be directly compared
            // because conversion from matrix to euler is not 1-to-1.
            Matrix33 rotMatrix3 = Matrix33FromEulerXYZ(eulerAngles2);
            Validate(IsSimilar(rotMatrix, rotMatrix3));
        }
    }
}



SetFunctionName("Transform(Vector3* vecs, int numVectors, Matrix33 matrix, Vector3 *transformedVecs)");
