        Vector3(-1.9694085f, 1.0340564f, 3.0086801f ),
        Vector3(-9.5688305f, -1.8745952f, 7.3432522f )
};
Vector3 res[3];
Transform( vec, 3, a, res );
Validate(   IsSimilar(res[0], ref[0]) &&
    IsSimilar(res[1], ref[1]) &&
    IsSimilar(res[2], ref[2]) );



